const b64u = (b: Buffer) => b.toString('base64url');

sign(claims): 
  header = { alg: 'HS256', typ: 'JWT' }
  payload = { ...claims, iat, exp: iat + ttl, iss, aud, jti: randomUUID(), nbf: iat }
  signingInput = `${b64u(JSON.stringify(header))}.${b64u(JSON.stringify(payload))}`
  sig = createHmac('sha256', secret).update(signingInput).digest()
  return `${signingInput}.${b64u(sig)}`

verify(token):
  split into 3 parts; decode header; check alg === 'HS256' exactly (prevent alg confusion); recompute sig; compare with timingSafeEqual (hash both sides to fixed length via createHash('sha256') to make lengths equal — or check lengths equal first; HMAC-SHA256 is always 32 bytes so length check + timingSafeEqual is fine; but to be extra safe, compare SHA-256 digests of both signatures with timingSafeEqual — that's the "buffer hashes" pattern).
  check exp > now, nbf <= now, iss === expected, aud === expected.

