export function createLoginHandler(authService: AuthService) {
  return async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    try {
      const input = validateLoginInput(req.body);
      if (!input.ok) { res.status(400).json({ error: 'validation_error', message: '...', details: input.errors }); return; }
      const ip = getClientIp(req);
      const result = await authService.login({ email: input.value.email, password: input.value.password, ip });
      res.status(200).json({ accessToken: result.accessToken, tokenType: 'Bearer', expiresIn: result.expiresIn });
    } catch (err) { next(err); }
  };
}
